import{_ as o,a0 as d,w as p,s as r,ao as n,I as l,x as i,a1 as a,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const m=JSON.parse('{"title":"在 Ubuntu 中用 UFW 配置防火墙 | LCTT x X-CMD","titleTemplate":false,"description":"在 Ubuntu 中用 UFW 配置防火墙 | LCTT (201701) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Ubuntu 中用 UFW 配置防火墙 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Ubuntu 中用 UFW 配置防火墙 | LCTT (201701) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201701/20161201 How to Configure a Firewall with UFW","title":"在 Ubuntu 中用 UFW 配置防火墙","tag":"201701","desc":""},"relativePath":"201701/20161201 How to Configure a Firewall with UFW.md","filePath":"[post].md"}'),h={name:"201701/20161201 How to Configure a Firewall with UFW.md"};function u(g,s,c,b,k,f){const e=d("Link");return p(),r("div",null,[s[26]||(s[26]=n('<h1 id="在-ubuntu-中用-ufw-配置防火墙" tabindex="-1">在 Ubuntu 中用 UFW 配置防火墙 <a class="header-anchor" href="#在-ubuntu-中用-ufw-配置防火墙" aria-label="Permalink to “在 Ubuntu 中用 UFW 配置防火墙”">​</a></h1><p>UFW，即简单防火墙（uncomplicated firewall），是一个 Arch Linux、Debian 或 Ubuntu 中管理防火墙规则的前端。 UFW 通过命令行使用（尽管它有可用的 GUI），它的目的是使防火墙配置简单（即不复杂（uncomplicated））。</p><p><img src="https://www.linode.com/docs/assets/ufw_tg.png" alt="How to Configure a Firewall with UFW" title="How to Configure a Firewall with UFW"></p><h3 id="开始之前" tabindex="-1">开始之前 <a class="header-anchor" href="#开始之前" aria-label="Permalink to “开始之前”">​</a></h3>',4)),l("p",null,[s[1]||(s[1]=i("1、 熟悉我们的",-1)),a(e,{href:"https://www.linode.com/docs/getting-started"},{default:t(()=>[...s[0]||(s[0]=[i("入门",-1)])]),_:1}),s[2]||(s[2]=i("指南，并完成设置服务器主机名和时区的步骤。",-1))]),l("p",null,[s[4]||(s[4]=i("2、 本指南将尽可能使用 ",-1)),s[5]||(s[5]=l("code",null,"sudo",-1)),s[6]||(s[6]=i("。 在完成",-1)),a(e,{href:"https://www.linode.com/docs/security/securing-your-server"},{default:t(()=>[...s[3]||(s[3]=[i("保护你的服务器",-1)])]),_:1}),s[7]||(s[7]=i("指南的章节，创建一个标准用户帐户，强化 SSH 访问和移除不必要的网络服务。 ",-1)),s[8]||(s[8]=l("strong",null,"但不要",-1)),s[9]||(s[9]=i("跟着创建防火墙部分 - 本指南是介绍使用 UFW 的，它对于 iptables 而言是另外一种控制防火墙的方法。",-1))]),s[27]||(s[27]=n('<p>3、 更新系统</p><p><strong>Arch Linux</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -Syu</span></span></code></pre></div><p><strong>Debian / Ubuntu</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get update &amp;&amp; sudo apt-get upgrade</span></span></code></pre></div><h3 id="安装-ufw" tabindex="-1">安装 UFW <a class="header-anchor" href="#安装-ufw" aria-label="Permalink to “安装 UFW”">​</a></h3><p>UFW 默认包含在 Ubuntu 中，但在 Arch 和 Debian 中需要安装。 Debian 将自动启用 UFW 的 systemd 单元，并使其在重新启动时启动，但 Arch 不会。 这与告诉 UFW 启用防火墙规则不同，因为使用 systemd 或者 upstart 启用 UFW 仅仅是告知 init 系统打开 UFW 守护程序。</p>',7)),l("p",null,[s[11]||(s[11]=i("默认情况下，UFW 的规则集为空，因此即使守护程序正在运行，也不会强制执行任何防火墙规则。 强制执行防火墙规则集的部分",-1)),a(e,{href:"http://localhost:4567/docs/security/firewalls/configure-firewall-with-ufw#enable-the-firewall"},{default:t(()=>[...s[10]||(s[10]=[i("在下面",-1)])]),_:1}),s[12]||(s[12]=i("。",-1))]),s[28]||(s[28]=n(`<h4 id="arch-linux" tabindex="-1">Arch Linux <a class="header-anchor" href="#arch-linux" aria-label="Permalink to “Arch Linux”">​</a></h4><p>1、 安装 UFW：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -S ufw</span></span></code></pre></div><p>2、 启动并启用 UFW 的 systemd 单元：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl start ufw</span></span>
<span class="line"><span>sudo systemctl enable ufw</span></span></code></pre></div><h4 id="debian-ubuntu" tabindex="-1">Debian / Ubuntu <a class="header-anchor" href="#debian-ubuntu" aria-label="Permalink to “Debian / Ubuntu”">​</a></h4><p>1、 安装 UFW</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install ufw</span></span></code></pre></div><h3 id="使用-ufw-管理防火墙规则" tabindex="-1">使用 UFW 管理防火墙规则 <a class="header-anchor" href="#使用-ufw-管理防火墙规则" aria-label="Permalink to “使用 UFW 管理防火墙规则”">​</a></h3><h4 id="设置默认规则" tabindex="-1">设置默认规则 <a class="header-anchor" href="#设置默认规则" aria-label="Permalink to “设置默认规则”">​</a></h4><p>大多数系统只需要打开少量的端口接受传入连接，并且关闭所有剩余的端口。 从一个简单的规则基础开始，<code>ufw default</code>命令可以用于设置对传入和传出连接的默认响应动作。 要拒绝所有传入并允许所有传出连接，那么运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ufw default allow outgoing</span></span>
<span class="line"><span>sudo ufw default deny incoming</span></span></code></pre></div><p><code>ufw default</code> 也允许使用 <code>reject</code> 参数。</p><blockquote><p>警告：</p></blockquote><blockquote><p>除非明确设置允许规则，否则配置默认 <code>deny</code> 或 <code>reject</code> 规则会锁定你的服务器。确保在应用默认 <code>deny</code> 或 <code>reject</code> 规则之前，已按照下面的部分配置了 SSH 和其他关键服务的允许规则。</p></blockquote><h4 id="添加规则" tabindex="-1">添加规则 <a class="header-anchor" href="#添加规则" aria-label="Permalink to “添加规则”">​</a></h4><p>可以有两种方式添加规则：用<strong>端口号</strong>或者<strong>服务名</strong>表示。</p><p>要允许 SSH 的 22 端口的传入和传出连接，你可以运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ufw allow ssh</span></span></code></pre></div><p>你也可以运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ufw allow 22</span></span></code></pre></div><p>相似的，要在特定端口（比如 111）上 <code>deny</code> 流量，你需要运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ufw deny 111</span></span></code></pre></div><p>为了更好地调整你的规则，你也可以允许基于 TCP 或者 UDP 的包。下面例子会允许 80 端口的 TCP 包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ufw allow 80/tcp</span></span>
<span class="line"><span>sudo ufw allow http/tcp</span></span></code></pre></div><p>这个会允许 1725 端口上的 UDP 包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ufw allow 1725/udp</span></span></code></pre></div><h4 id="高级规则" tabindex="-1">高级规则 <a class="header-anchor" href="#高级规则" aria-label="Permalink to “高级规则”">​</a></h4><p>除了基于端口的允许或阻止，UFW 还允许您按照 IP 地址、子网和 IP 地址/子网/端口的组合来允许/阻止。</p><p>允许从一个 IP 地址连接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ufw allow from 123.45.67.89</span></span></code></pre></div><p>允许特定子网的连接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ufw allow from 123.45.67.89/24</span></span></code></pre></div><p>允许特定 IP/ 端口的组合：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ufw allow from 123.45.67.89 to any port 22 proto tcp</span></span></code></pre></div><p><code>proto tcp</code> 可以删除或者根据你的需求改成 <code>proto udp</code>，所有例子的 <code>allow</code> 都可以根据需要变成 <code>deny</code>。</p><h4 id="删除规则" tabindex="-1">删除规则 <a class="header-anchor" href="#删除规则" aria-label="Permalink to “删除规则”">​</a></h4><p>要删除一条规则，在规则的前面加上 <code>delete</code>。如果你希望不再允许 HTTP 流量，你可以运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ufw delete allow 80</span></span></code></pre></div><p>删除规则同样可以使用服务名。</p><h3 id="编辑-ufw-的配置文件" tabindex="-1">编辑 UFW 的配置文件 <a class="header-anchor" href="#编辑-ufw-的配置文件" aria-label="Permalink to “编辑 UFW 的配置文件”">​</a></h3><p>虽然可以通过命令行添加简单的规则，但仍有可能需要添加或删除更高级或特定的规则。 在运行通过终端输入的规则之前，UFW 将运行一个文件 <code>before.rules</code>，它允许回环接口、ping 和 DHCP 等服务。要添加或改变这些规则，编辑 <code>/etc/ufw/before.rules</code> 这个文件。 同一目录中的 <code>before6.rules</code> 文件用于 IPv6 。</p><p>还存在一个 <code>after.rule</code> 和 <code>after6.rule</code> 文件，用于添加在 UFW 运行你通过命令行输入的规则之后需要添加的任何规则。</p><p>还有一个配置文件位于 <code>/etc/default/ufw</code>。 从此处可以禁用或启用 IPv6，可以设置默认规则，并可以设置 UFW 以管理内置防火墙链。</p><h3 id="ufw-状态" tabindex="-1">UFW 状态 <a class="header-anchor" href="#ufw-状态" aria-label="Permalink to “UFW 状态”">​</a></h3><p>你可以在任何时候使用命令：<code>sudo ufw status</code> 查看 UFW 的状态。这会显示所有规则列表，以及 UFW 是否处于激活状态：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Status: active</span></span>
<span class="line"><span></span></span>
<span class="line"><span>To                         Action      From</span></span>
<span class="line"><span>--                         ------      ----</span></span>
<span class="line"><span>22                         ALLOW       Anywhere</span></span>
<span class="line"><span>80/tcp                     ALLOW       Anywhere</span></span>
<span class="line"><span>443                        ALLOW       Anywhere</span></span>
<span class="line"><span>22 (v6)                    ALLOW       Anywhere (v6)</span></span>
<span class="line"><span>80/tcp (v6)                ALLOW       Anywhere (v6)</span></span>
<span class="line"><span>443 (v6)                   ALLOW       Anywhere (v6)</span></span></code></pre></div><h3 id="启用防火墙" tabindex="-1">启用防火墙 <a class="header-anchor" href="#启用防火墙" aria-label="Permalink to “启用防火墙”">​</a></h3><p>随着你选择规则完成，你初始运行 <code>ufw status</code> 可能会输出 <code>Status: inactive</code>。 启用 UFW 并强制执行防火墙规则：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ufw enable</span></span></code></pre></div><p>相似地，禁用 UFW 规则：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ufw disable</span></span></code></pre></div><blockquote><p>UFW 会继续运行，并且在下次启动时会再次启动。</p></blockquote><h3 id="日志记录" tabindex="-1">日志记录 <a class="header-anchor" href="#日志记录" aria-label="Permalink to “日志记录”">​</a></h3><p>你可以用下面的命令启动日志记录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ufw logging on</span></span></code></pre></div><p>可以通过运行 <code>sudo ufw logging low|medium|high</code> 设计日志级别，可以选择 <code>low</code>、 <code>medium</code> 或者 <code>high</code>。默认级别是 <code>low</code>。</p><p>常规日志类似于下面这样，位于 <code>/var/logs/ufw</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Sep 16 15:08:14 &lt;hostname&gt; kernel: [UFW BLOCK] IN=eth0 OUT= MAC=00:00:00:00:00:00:00:00:00:00:00:00:00:00 SRC=123.45.67.89 DST=987.65.43.21 LEN=40 TOS=0x00 PREC=0x00 TTL=249 ID=8475 PROTO=TCP SPT=48247 DPT=22 WINDOW=1024 RES=0x00 SYN URGP=0</span></span></code></pre></div><p>前面的值列出了你的服务器的日期、时间、主机名。剩下的重要信息包括：</p><ul><li><strong>[UFW BLOCK]</strong>：这是记录事件的描述开始的位置。在此例中，它表示阻止了连接。</li><li><strong>IN</strong>：如果它包含一个值，那么代表该事件是传入事件</li><li><strong>OUT</strong>：如果它包含一个值，那么代表事件是传出事件</li><li><strong>MAC</strong>：目的地和源 MAC 地址的组合</li><li><strong>SRC</strong>：包源的 IP</li><li><strong>DST</strong>：包目的地的 IP</li><li><strong>LEN</strong>：数据包长度</li><li><strong>TTL</strong>：数据包 TTL，或称为 time to live。 在找到目的地之前，它将在路由器之间跳跃，直到它过期。</li><li><strong>PROTO</strong>：数据包的协议</li><li><strong>SPT</strong>：包的源端口</li><li><strong>DPT</strong>：包的目标端口</li><li><strong>WINDOW</strong>：发送方可以接收的数据包的大小</li><li><strong>SYN URGP</strong>：指示是否需要三次握手。 <code>0</code> 表示不需要。</li></ul><hr>`,62)),l("p",null,[s[14]||(s[14]=i("via: ",-1)),a(e,{href:"https://www.linode.com/docs/security/firewalls/configure-firewall-with-ufw"},{default:t(()=>[...s[13]||(s[13]=[i("https://www.linode.com/docs/security/firewalls/configure-firewall-with-ufw",-1)])]),_:1})]),l("p",null,[s[18]||(s[18]=i("作者：",-1)),a(e,{href:"https://www.linode.com/docs/security/firewalls/configure-firewall-with-ufw"},{default:t(()=>[...s[15]||(s[15]=[i("Linode",-1)])]),_:1}),s[19]||(s[19]=i(" 译者：",-1)),a(e,{href:"https://github.com/geekpi"},{default:t(()=>[...s[16]||(s[16]=[i("geekpi",-1)])]),_:1}),s[20]||(s[20]=i(" 校对：",-1)),a(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[17]||(s[17]=[i("wxy",-1)])]),_:1})]),l("p",null,[s[23]||(s[23]=i("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[21]||(s[21]=[i("LCTT",-1)])]),_:1}),s[24]||(s[24]=i(" 原创编译，",-1)),a(e,{href:"https://linux.cn/"},{default:t(()=>[...s[22]||(s[22]=[i("Linux中国",-1)])]),_:1}),s[25]||(s[25]=i(" 荣誉推出",-1))])])}const C=o(h,[["render",u]]);export{m as __pageData,C as default};
